import os
import random
import struct
from typing import List

# This generator produces arbitrary binary data optimized for exercising xxHash paths.
# Goals:
# - Provide a wide range of buffer sizes, especially around algorithmic thresholds:
#   * 0 bytes
#   * very small (< 16/32)
#   * around 16, 32, 64, 128, 136 (XXH3 secret min), 240, 512, 1024, 2048
# - Include varied content patterns: zeros, 0xFF, incremental, alternating, high-entropy random,
#   ASCII text, UTF-8-like, repeating sequences, primes, misaligned prefixes, etc.
# - Keep size <= 2048 to align with fuzz stubs.
# - Return bytes suitable for FUZZ_PARAM_STR() which becomes std::string byte data.

MAX_SIZE = 2048

def _rand(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n

def _pattern_ff(n: int) -> bytes:
    return b"\xFF" * n

def _pattern_inc(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))

def _pattern_alt(n: int, a: int = 0x55, b: int = 0xAA) -> bytes:
    return bytes((a if (i & 1) == 0 else b) for i in range(n))

def _pattern_repeat(chunk: bytes, n: int) -> bytes:
    if not chunk:
        return b""
    reps = (n + len(chunk) - 1) // len(chunk)
    return (chunk * reps)[:n]

def _ascii_text(n: int) -> bytes:
    base = (b"The quick brown fox jumps over the lazy dog. "
            b"Pack my box with five dozen liquor jugs. ")
    return _pattern_repeat(base, n)

def _utf8_like(n: int) -> bytes:
    seqs = [
        b"\xc3\xa9",  # é
        b"\xce\xbb",  # λ
        b"\xe2\x82\xac",  # €
        b"\xf0\x9f\x98\x80",  # 😀
        b" ", b"-", b"_",
    ]
    out = bytearray()
    i = 0
    while len(out) < n:
        out += seqs[i % len(seqs)]
        i += 1
    return bytes(out[:n])

def _primes_bytes(n: int) -> bytes:
    # Simple LCG-like progression with prime steps for variety
    val = 0x9E3779B1
    out = bytearray()
    primes = [3,5,7,11,13,17,19,23]
    pi = 0
    while len(out) < n:
        val = (val * 2654435761 + primes[pi]) & 0xFFFFFFFF
        out.append((val >> 24) & 0xFF)
        pi = (pi + 1) % len(primes)
    return bytes(out[:n])

def _misaligned_prefix(rng: random.Random, n: int) -> bytes:
    # Add a 0..7 byte prefix then fill with random
    prefix = rng.randrange(0, 8)
    core = max(0, n - prefix)
    return _pattern_inc(prefix, start=prefix) + _rand(rng, core)

def _secret_like(rng: random.Random, n: int) -> bytes:
    # XXH3 secret should be high-entropy random-like; include some structure variety
    # Mix random with repeated lanes to keep valid but diverse
    block = bytearray()
    while len(block) < n:
        choice = rng.randrange(4)
        if choice == 0:
            block += _rand(rng, min(64, n - len(block)))
        elif choice == 1:
            lane = struct.pack('<Q', rng.getrandbits(64))
            block += _pattern_repeat(lane, min(64, n - len(block)))
        elif choice == 2:
            block += _pattern_alt(min(64, n - len(block)))
        else:
            block += _pattern_inc(min(64, n - len(block)), start=rng.randrange(256))
    return bytes(block[:n])

def _choose_sizes(rng: random.Random) -> List[int]:
    # Sizes tuned for both data and secret buffers
    candidates = [
        0, 1, 2, 3, 4, 7, 8, 15, 16, 17, 31, 32, 33,
        63, 64, 65, 127, 128, 129, 135, 136, 137,
        240, 255, 256, 511, 512, 1023, 1024, 1536, 2047, 2048
    ]
    # Add a couple of random sizes
    for _ in range(3):
        candidates.append(rng.randrange(0, MAX_SIZE + 1))
    rng.shuffle(candidates)
    return candidates

def _make_buffer(rng: random.Random, n: int) -> bytes:
    # Select a content strategy
    strategies = [
        lambda: _rand(rng, n),
        lambda: _pattern_zero(n),
        lambda: _pattern_ff(n),
        lambda: _pattern_inc(n, start=rng.randrange(256)),
        lambda: _pattern_alt(n),
        lambda: _pattern_repeat(b"ABCDEF0123456789", n),
        lambda: _ascii_text(n),
        lambda: _utf8_like(n),
        lambda: _primes_bytes(n),
        lambda: _misaligned_prefix(rng, n),
    ]
    # Bias towards random for secrets/data
    weights = [4,1,1,2,2,1,1,1,1,2]
    strat = rng.choices(strategies, weights=weights, k=1)[0]
    return strat()

def _compose_interesting_payload(rng: random.Random) -> bytes:
    # Build a payload that can serve as either data or secret depending on stub usage.
    # Layout: [section_count(1)][sections...]
    # Each section: [tag(1)] [len(2 BE)] [bytes]
    # Tags:
    # 0x01: data blob
    # 0x02: candidate secret (>=136 enforced)
    # 0x03: ASCII text blob
    # 0x04: high-entropy blob
    # 0x05: repeating pattern
    # The fuzzer stubs only take a single FUZZ_PARAM_STR at a time; this container still yields
    # valid arbitrary data for hashing, while also being useful if a harness splits it.

    sections = bytearray()
    sizes = _choose_sizes(rng)

    # Ensure we include at least one 0-len and one boundary and one secret-like >=136
    chosen = []
    chosen.append(0)
    chosen.append(16)
    chosen.append(32)
    chosen.append(136)
    chosen.append(2048)
    # Add a couple random picks
    for _ in range(3):
        chosen.append(sizes[rng.randrange(len(sizes))])

    rng.shuffle(chosen)

    total = 1  # section count byte will be here
    built = []

    for n in chosen:
        if n > MAX_SIZE:
            n = MAX_SIZE
        # stop if adding would exceed MAX_SIZE overall
        # worst-case header per section = 3 bytes
        if total + 3 + n > MAX_SIZE:
            continue
        tag = rng.choice([0x01,0x02,0x03,0x04,0x05])
        if tag == 0x02 and n < 136:
            n = 136
        if n > MAX_SIZE or total + 3 + n > MAX_SIZE:
            continue
        if tag == 0x02:
            content = _secret_like(rng, n)
        elif tag == 0x03:
            content = _ascii_text(n)
        elif tag == 0x04:
            content = _rand(rng, n)
        elif tag == 0x05:
            patt = rng.choice([b"\x00", b"\xFF", b"AB", b"\x55\xAA", b"01234567"])  # short seed
            content = _pattern_repeat(patt, n)
        else:
            content = _make_buffer(rng, n)
        built.append((tag, content))
        total += 3 + n

    if not built:
        # Fallback: simple random buffer
        n = rng.randrange(0, MAX_SIZE + 1)
        return _rand(rng, n)

    sections.append(len(built) & 0xFF)
    for tag, content in built:
        sections.append(tag & 0xFF)
        sections += struct.pack('>H', len(content))
        sections += content

    return bytes(sections)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide between simple flat buffer or containerized payload
    mode = rng.randrange(0, 100)
    if mode < 55:
        # Flat buffer, typical for data hashing paths
        size = rng.choice(_choose_sizes(rng))
        if size < 0:
            size = 0
        if size > MAX_SIZE:
            size = MAX_SIZE
        # For a chance to produce valid XXH3 secret buffers when used as secret, bias to >=136
        if rng.random() < 0.25 and size < 136:
            size = 136
        # Choose content with a bias towards random/high-entropy
        if rng.random() < 0.4:
            buf = _rand(rng, size)
        elif rng.random() < 0.2:
            buf = _secret_like(rng, size)
        else:
            buf = _make_buffer(rng, size)
        return buf
    else:
        # Containerized payload packing multiple interesting segments
        return _compose_interesting_payload(rng)
